def match(orders):
    trades = []
    # Bids: price -> list of (order_id, qty, arrival_time)
    # Asks: price -> list of (order_id, qty, arrival_time)
    bids = {}
    asks = {}
    # Track order states: id -> (side, price, filled_qty, arrival_time)
    order_state = {}
    arrival_counter = 0

    for order in orders:
        arrival_counter += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_state:
                side, price, filled_qty, arrival_time = order_state[order_id]
                if filled_qty < price:  # Not fully filled
                    if side == 'buy':
                        if price in bids:
                            bids[price] = [(oid, qty) for oid, qty in bids[price] if oid != order_id]
                            if not bids[price]:
                                del bids[price]
                    else:  # sell
                        if price in asks:
                            asks[price] = [(oid, qty) for oid, qty in asks[price] if oid != order_id]
                            if not asks[price]:
                                del asks[price]
                del order_state[order_id]

